  private val shiftHi = bits - point - 1
  private val shiftLo = -(point + 1)
  require(
    intBits >= log2Ceil(math.max(shiftHi, -shiftLo) + 1) + 1,
    s"intBits=$intBits cannot hold exponents in [$shiftLo, $shiftHi]",
